Dense output = Dense.builder()
        .units(3)
        .activation(Activation.SOFTMAX)
        .seed(7L)
        .build();

Tensor<BC> features = Tensor.ofBC(2, 4, new double[2 * 4]);
Tensor<BC> probabilities = output.forward(features);

Dense hidden = Dense.builder()
        .units(8)
        .activation(Activation.RELU)
        .build();

Conv2D conv = Conv2D.builder()
        .filters(8)
        .kernelSize(3, 3)
        .strides(1, 1)
        .padding(Padding.SAME)
        .activation(Activation.RELU)
        .seed(7L)
        .build();

Tensor<BCHW> input = Tensor.ofBCHW(2, 3, 8, 8, new double[2 * 3 * 8 * 8]);
Tensor<BCHW> featureMap = conv.forward(input);

Tensor<BCHW> gradient = Tensor.zerosBCHW(2, 8, 8, 8);
conv.backward(gradient);
conv.update(new OptimizerConfig(Optimizer.ADAM, 0.001, 0.9, 0.999, 1e-8));

Dense dense = Dense.builder()
        .units(10)
        .activation(Activation.RELU)
        .seed(1L)
        .build();

Tensor<BC> input = Tensor.ofBC(4, 6, new double[4 * 6]);
Tensor<BC> hidden = dense.forward(input);

dense.backward(Tensor.zerosBC(4, 10));
dense.update(Optimizer.SGD.withLearningRate(0.01));

Flatten flatten = Flatten.builder().build();

Tensor<BCHW> featureMap = Tensor.ofBCHW(2, 4, 3, 3, new double[2 * 4 * 3 * 3]);
Tensor<BC> flat = flatten.forward(featureMap);

Tensor<BCHW> restored = flatten.backward(flat);

Layer<BC, BC> identity = new Layer<>() {
    @Override
    public Tensor<BC> forward(Tensor<BC> input) {
        return input;
    }

    @Override
    public Tensor<BC> backward(Tensor<BC> gradient) {
        return gradient;
    }
};

Tensor<BC> output = identity.forward(Tensor.zerosBC(2, 3));
int parameterCount = identity.parameters().size();

MaxPooling2D pool = MaxPooling2D.builder()
        .poolSize(2, 2)
        .strides(2, 2)
        .build();

Tensor<BCHW> input = Tensor.ofBCHW(1, 1, 4, 4, new double[16]);
Tensor<BCHW> pooled = pool.forward(input);

Tensor<BCHW> gradient = Tensor.zerosBCHW(1, 1, 2, 2);
Tensor<BCHW> inputGradient = pool.backward(gradient);

Conv2D same = Conv2D.builder()
        .filters(4)
        .kernelSize(3, 3)
        .padding(Padding.SAME)
        .build();

Conv2D valid = Conv2D.builder()
        .filters(4)
        .kernelSize(3, 3)
        .padding(Padding.VALID)
        .build();

Tensor<BCHW> input = Tensor.zerosBCHW(1, 2, 7, 7);
int sameWidth = same.forward(input).dimension(3);
int validWidth = valid.forward(input).dimension(3);
